ALTER POLICY "orcamentos comercial leitura" ON public.orcamentos USING ((organization_id IS NOT NULL AND (public.is_organization_member(organization_id) OR public.has_role(auth.uid(),'admin'::public.app_role))) OR (organization_id IS NULL AND user_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.orcamento_shares s WHERE s.orcamento_id=orcamentos.id AND public.is_organization_member(s.organization_id)));